// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import {Test, console} from "forge-std/Test.sol";
import "../src/list_dos.sol";

contract GovernmentTest is Test {
    Government gov;
    address deployer = makeAddr("deployer");
    address lender = makeAddr("lender");
    address trigger = makeAddr("trigger");

    function setUp() public {
        vm.deal(deployer, 100 ether);
        vm.deal(lender, 20 ether);
        vm.deal(trigger, 1 ether);

        vm.prank(deployer);
        gov = new Government{value: 10 ether}();
    }

    function testPredictableResetTrigger() public {
        // Create a valid loan within initial timeframe
        vm.prank(lender);
        gov.lendGovernmentMoney{value: 1 ether}(address(0));

        // Warp forward to EXACTLY 12 hours later + 1 second
        vm.warp(block.timestamp + 12 hours + 1);

        // Record pre-reset state
        uint256 preResetRound = gov.round();
        uint256 preResetBalance = address(gov).balance;

        // Trigger reset with small transaction
        vm.prank(trigger);
        bool result = gov.lendGovernmentMoney{value: 1 ether}(address(0));

        // Verify reset condition was triggered
        assertFalse(result, "Reset should return false");
        assertEq(gov.round(), preResetRound + 1, "Round not incremented");
        assertEq(gov.profitFromCrash(), 0, "Crash profits not reset");
        assertEq(gov.getCreditorAddresses().length, 0, "Creditors not cleared");
        assertLt(
            address(gov).balance, 
            preResetBalance - 1 ether, 
            "Incorrect balance after reset"
        );
    }
}
